"""Build a self-contained offline fight preview, with literal art URLs embedded."""
from pathlib import Path
import re, base64, mimetypes, zipfile, sys
root=Path(__file__).resolve().parents[1]
out=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else root.parent.parent/'devourer-first-fight-playtest.zip'
s=(root/'index.html').read_text()
def script(m):return '<script>\n'+(root/m[1]).read_text().replace('</script','<\\/script')+'\n</script>'
s=re.sub(r'<script src="([^"]+)"></script>',script,s)
def asset(m):
 p=root/m[2]
 return m[1]+'data:'+mimetypes.guess_type(p.name)[0]+';base64,'+base64.b64encode(p.read_bytes()).decode()+m[1] if p.is_file() else m[0]
s=re.sub(r"(['\"])(art/[^'\"]+\.(?:png|webp))\1",asset,s)
s=s.replace("localStorage.getItem('","localStorage.getItem('devourer-trial:").replace("localStorage.setItem('","localStorage.setItem('devourer-trial:")
ui='''<aside style="max-width:960px;margin:12px auto;padding:12px;background:#242231;color:#ffe0aa;font:14px monospace"><button onclick="startDevourerPreview()">Restart ambush</button> <button onclick="practiceDevourerKefir()">Kefir spray</button> <button onclick="practiceDevourerPogo()">Pogo practice</button> <button onclick="practiceDevourerDefeat()">Defeat animation</button> <button onclick="practiceDevourerDoor()">Upward shot practice</button> <button onclick="practiceDevourerShelter()">Shelter practice</button> <button onclick="respawnCheckpoint()">Retry checkpoint</button> <button onclick="leaveDevourerPreview()">Full Bakery 3</button><p>Arrows move · Space jump · X shoot · Jump + shoot fires UP · V uses stored kefir. Release jump for horizontal airborne shots. C toggles pogo: land on the small pale ceramic cap. Shelter is at the far right.</p></aside>'''
js="function practiceDevourerDoor(){startDevourerPreview();devourerState.phase='recovery';devourerState.timer=108;devourerState.x=91*T;devourerGate(true);player.x=devourerState.x-player.w/2;player.y=54*T-player.h;player.ground=true;}function practiceDevourerShelter(){startDevourerPreview();devourerState.phase='rest';devourerState.timer=60;devourerState.cycle=1;devourerGate(true);player.x=102*T;player.y=54*T-player.h;player.ground=true;}function practiceDevourerKefir(){startDevourerPreview();devourerState.x=94*T;devourerState.cycle=1;devourerState.phase='landing';devourerState.timer=30;devourerGate(true);player.x=90*T;}function practiceDevourerPogo(){startDevourerPreview();devourerState.x=90*T;devourerState.cycle=1;devourerState.phase='rest';devourerState.timer=180;devourerGate(true);player.x=87*T;player.y=51*T-player.h;player.ground=true;}function practiceDevourerDefeat(){startDevourerPreview();devourerState.x=94*T;devourerState.health=1;hurtDevourer();player.x=87*T;}startDevourerPreview();"
s=s.replace('<body>','<body>'+ui).replace('</body>','<script>'+js+'</script></body>')
assert '<script src=' not in s
out.with_suffix('.html').write_text(s)
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
 z.writestr('Bakery-3.html',s)
 z.writestr('START-HERE.txt','Extract and open Bakery-3.html in Chrome, Edge or Firefox. All artwork/scripts are embedded.\nWalk toward the supposed final oven. Move quickly when it leaps; the first landing target locks at takeoff. Later leaps show a landing stripe during the longer piston warning, lock their target early, travel at most five tiles and move more slowly. A full cooling beat lets you reposition between attacks. After a half-second landing beat, attacks alternate between five bouncing flaming boules and seven spaced kefir droplets. Kefir leaves at most two brief puddles outside the shelter; all liquid clears when the door opens. Then comes then a pressure-release beat and a one-second opening. The vent extinguishes remaining boules, giving a clean chance to attack. His door stays open throughout the leap: fire UP into the furnace while he is overhead. It closes on landing and reopens during recovery. Jump+shoot now fires UP. Get beneath the exposed furnace, or jump then release jump and shoot horizontally from the side. The far-right low service shelter fits the baker, blocks boules, and stops the boss outside. Kefir is stored: press V or tap Kefir to activate an8-second boost at8.1px/tick (50% faster than before). One charge is provided on start/retry and another bottle waits in the shelter. An ammo cache near the shelter entrance gives25 ammo and refreshes every5 seconds; its countdown shows when it is ready. Player firing is50% faster. Boss jumps twice as high and falls about30% slower. Closed armor blocks shots.\nArrows move; Space jumps (hold for height); X shoots; jump+X fires upward; V activates stored kefir; P pauses; R restarts. Preview buttons restart the ambush, practice upward shots or the shelter, retry the checkpoint, or return to the original full Bakery 3.\nThe ceramic pressure cap is the only vulnerable roof target: C toggles pogo; land precisely on the pale cap. Other armor clangs and rebounds without damage. Defeat now falls, buckles, vents and settles into a generated cold wreck. New practice buttons preview kefir, pogo and defeat. This remains isolated; full Bakery 3 level redesign/integration follows approval. Battle health and previously approved movement/barrage/opening timing are unchanged.\n')
with zipfile.ZipFile(out) as z:assert z.testzip() is None;assert z.read('Bakery-3.html').decode()==s
print(out)
